const $=s=>document.querySelector(s),fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`,parse=s=>/^\d+:[0-5]\d$/.test(s)?Number(s.split(':')[0])*60+Number(s.split(':')[1]):NaN;
const data={'테란':[['서플라이 디포',40,'building','▱'],['배럭',65,'building','▥'],['리파이너리',40,'building','◈'],['엔지니어링 베이',45,'building','⌘'],['미사일 터렛',30,'building','⌁'],['마린',24,'unit','♙'],['메딕',30,'unit','✚'],['팩토리',60,'building','▦'],['아카데미',50,'building','⌂']], '저그':[['스포닝 풀',60,'building','◉'],['익스트랙터',40,'building','◈'],['해처리',100,'building','⬡'],['레어',80,'building','◇'],['스파이어',80,'building','♧'],['뮤탈리스크',40,'unit','⋈'],['저글링',28,'unit','⌁'],['오버로드',40,'unit','◌']], '프로토스':[['파일런',30,'building','◇'],['게이트웨이',60,'building','◫'],['어시밀레이터',40,'building','◈'],['포지',45,'building','⌘'],['포톤 캐논',40,'building','◎'],['질럿',40,'unit','♙'],['드라군',50,'unit','♧'],['사이버네틱스 코어',60,'building','⬡']]};
let blocks=[],selected=null,side='me',filter='all',scale=2,responseId=null,target=330,travel=0,nextId=100;
function seed(){blocks=[['me','서플라이 디포',40,40],['me','배럭',85,65],['me','리파이너리',155,40],['me','마린',150,24],['me','마린',174,24],['me','서플라이 디포',200,40],['me','아카데미',210,50],['me','엔지니어링 베이',250,45],['me','미사일 터렛',280,30],['enemy','스포닝 풀',45,60],['enemy','익스트랙터',110,40],['enemy','해처리',130,100],['enemy','레어',130,80],['enemy','스파이어',210,80],['enemy','뮤탈리스크',290,40]].map((a,i)=>({id:i+1,side:a[0],name:a[1],start:a[2],duration:a[3],note:''}));selected=9;responseId=9;target=330;travel=0;nextId=100;$('#target').value='05:30';$('#travel').value=0;$('#projectName').value='5:30 뮤탈, 그 전에 준비하기';}
function save(){try{localStorage.setItem('buildlab-v1',JSON.stringify({blocks,responseId,target,travel,name:$('#projectName').value,nextId}));}catch(e){$('#saved').textContent='저장 공간을 사용할 수 없습니다';}}
function toast(s){$('#toast').textContent=s;$('#toast').style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.opacity=0,2200)}
function renderCatalog(){const el=$('#catalog');el.replaceChildren();data[$('#race').value].filter(x=>(filter==='all'||x[2]===filter)&&x[0].includes($('#search').value.trim())).forEach(x=>{const b=document.createElement('button');b.className='catalogItem';b.innerHTML=`<span class="glyph">${x[3]}</span><span><b>${x[0]}</b><small>${x[1]}s · ${x[2]==='unit'?'유닛':'건물'}</small></span><em>＋</em>`;b.onclick=()=>{const last=blocks.filter(a=>a.side===side).reduce((m,a)=>Math.max(m,a.start+a.duration),0);const item={id:nextId++,side,name:x[0],start:last,duration:x[1],note:''};blocks.push(item);selected=item.id;render();toast(`${x[0]} 추가됨 · ${fmt(last)}`);$('#scroll').scrollTop=Math.max(0,last*scale-160)};el.append(b)});if(!el.children.length)el.textContent='검색 결과가 없습니다.';}
function lanes(items){const ends=[];return items.sort((a,b)=>a.start-b.start||a.id-b.id).map(b=>{let lane=ends.findIndex(t=>t<=b.start);if(lane<0)lane=ends.length;ends[lane]=b.start+b.duration;return {b,lane}}).map((x,i,a)=>({...x,count:Math.max(1,...a.map(y=>y.lane+1))}));}
function render(){const timeline=$('#timeline');timeline.replaceChildren();timeline.className='timeline';const limit=Math.max(420,Math.ceil((Math.max(target+travel,...blocks.map(b=>b.start+b.duration))+30)/60)*60);timeline.style.height=(limit*scale+35)+'px';const axis=document.createElement('div');axis.className='axis';timeline.append(axis);for(let t=0;t<=limit;t+=30){let line=document.createElement('div');line.className='gridline';line.style.top=(t*scale+20)+'px';line.innerHTML=`<span class="tick">${fmt(t)}</span>`;timeline.append(line)}
for(const team of ['me','enemy']){for(const {b,lane,count} of lanes(blocks.filter(b=>b.side===team))){const el=document.createElement('button');el.className='buildBlock '+(team==='enemy'?'enemy ':'')+(selected===b.id?'selected':'');el.style.top=(b.start*scale+20)+'px';el.style.height=(b.duration*scale)+'px';el.style.left=`calc(${team==='me'?0:50}% + ${team==='me'?10:31}px + (50% - 46px) * ${lane/count})`;el.style.width=`calc((50% - 46px) / ${count} - 4px)`;el.title=`${b.name} ${fmt(b.start)} → ${fmt(b.start+b.duration)} (${b.duration}초)`;const title=document.createElement('b');title.textContent=b.name;const small=document.createElement('small');small.textContent=`${fmt(b.start)} → ${fmt(b.start+b.duration)}`;el.append(title,small);el.onclick=()=>{selected=b.id;render()};el.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();b.start=Math.max(0,b.start+(e.key==='ArrowUp'?-1:1)*(e.shiftKey?10:1));render()}};el.onpointerdown=e=>{if(e.button!==0)return;const y=e.clientY,original=b.start;let moved=false;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{if(Math.abs(ev.clientY-y)>5)moved=true;if(moved){b.start=Math.max(0,Math.round((original+(ev.clientY-y)/scale)/5)*5);el.style.top=(b.start*scale+20)+'px';small.textContent=`${fmt(b.start)} → ${fmt(b.start+b.duration)}`}};el.onpointerup=()=>{el.onpointermove=null;selected=b.id;render()};el.onpointercancel=()=>{b.start=original;el.onpointermove=null;render()}};timeline.append(el)}}
const marker=document.createElement('div');marker.className='marker';marker.style.top=(target+travel)*scale+20+'px';marker.innerHTML=`<span>${fmt(target+travel)} ${travel?'예상 도착':'상대 목표'}</span>`;timeline.append(marker);
const select=$('#response');select.replaceChildren();const none=document.createElement('option');none.value='';none.textContent='대응 항목 선택';select.append(none);blocks.filter(b=>b.side==='me').forEach(b=>{const opt=document.createElement('option');opt.value=b.id;opt.textContent=`${b.name} · ${fmt(b.start+b.duration)}`;select.append(opt)});if(!blocks.some(b=>b.id===responseId))responseId=null;select.value=responseId||'';$('#targetTime').textContent=fmt(target);const response=blocks.find(b=>b.id===responseId);$('#result').className='timingResult';if(response){const diff=target+travel-response.start-response.duration;$('#result').classList.toggle('late',diff<0);$('#result').innerHTML=`<strong>${diff<0?'+':'−'}${Math.abs(diff)}초</strong>${diff>=0?'상대 타이밍보다 먼저 준비됩니다':'상대 타이밍보다 준비가 늦습니다'}`}else $('#result').textContent='내 대응 항목을 선택하세요.';
const b=blocks.find(b=>b.id===selected);$('#editForm').hidden=!b;$('#empty').hidden=!!b;if(b){$('#editName').textContent=b.name;$('#owner').textContent=b.side==='me'?'내 빌드':'상대 빌드';$('#start').value=fmt(b.start);$('#duration').value=b.duration;$('#end').textContent=fmt(b.start+b.duration);$('#note').value=b.note}save();}
$('#editForm').onsubmit=e=>{e.preventDefault();const b=blocks.find(b=>b.id===selected),s=parse($('#start').value),d=Number($('#duration').value);if(!b||!Number.isFinite(s)||s>7200||d<1||d>600||!Number.isInteger(d)){toast('시각은 120분 이내, 소요 시간은 1~600초로 입력하세요.');return}b.start=s;b.duration=d;b.note=$('#note').value;render();toast('빌드 타이밍을 변경했습니다.')};$('#delete').onclick=()=>{blocks=blocks.filter(b=>b.id!==selected);selected=null;render();toast('블록을 삭제했습니다.')};$('#response').onchange=e=>{responseId=Number(e.target.value)||null;render()};$('#target').onchange=e=>{const t=parse(e.target.value);if(!Number.isFinite(t)||t>7200){e.target.value=fmt(target);toast('분:초 형식으로 120분 이내를 입력하세요.');return}target=t;render()};$('#travel').onchange=e=>{travel=Math.max(0,Math.min(300,Math.round(Number(e.target.value)||0)));e.target.value=travel;render()};$('#zoom').onchange=e=>{scale=Number(e.target.value);render()};$('#search').oninput=renderCatalog;$('#race').onchange=renderCatalog;$('#projectName').oninput=save;document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;document.querySelectorAll('[data-side]').forEach(x=>x.classList.toggle('active',x===b));$('#race').value=side==='me'?'테란':'저그';renderCatalog()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCatalog()});$('#reset').onclick=()=>{if(confirm('현재 연구를 초기 예제로 되돌릴까요?')){seed();render();toast('5:30 뮤탈 예제를 불러왔습니다.')}};
seed();try{const state=JSON.parse(localStorage.getItem('buildlab-v1'));if(state&&Array.isArray(state.blocks)){blocks=state.blocks;responseId=state.responseId;target=state.target;travel=state.travel;nextId=state.nextId;$('#projectName').value=state.name;$('#target').value=fmt(target);$('#travel').value=travel;selected=blocks.find(b=>b.side==='me')?.id}}catch(e){}renderCatalog();render();
